krb5_int32 prepare_kdc_request(krb5_kdc_req *request, krb5_principal *krbtgt_princ) {
    krb5_int32 ret = 0;
    krb5_boolean need_reprocess = KRB5_KDC_REQUEST_HAS_FLAG(request, KRB5_KDCREQ_CANONICALIZE);

    if (!need_reprocess) {
        return 0;
    }

    if (krbtgt_princ == NULL || krbtgt_princ->name.name_string.len <= 0) {
        return KRB5_BAD_PRINCIPAL;
    }

    krb5_principal server_princ = request->client;

    if (server_princ == NULL || server_princ->name.name_string.len <= 0) {
        return KRB5_BAD_PRINCIPAL;
    }

    char *fqdn = NULL;
    ret = krb5_principal_get_fqdn(server_princ, &fqdn);
    if (ret != 0) {
        return ret;
    }

    if (fqdn == NULL) {
        free(fqdn);
        return KRB5_KDC_INTERNAL;
    }

    krb5_realm target_realm = NULL;
    ret = krb5_map_fqdn_to_realm(fqdn, &target_realm);
    if (ret != 0) {
        free(fqdn);
        return ret;
    }

    if (target_realm == NULL || strcmp(target_realm, server_princ->realm) == 0) {
        free(fqdn);
        return 0;
    }

    krb5_principal cross_realm_tgt = NULL;
    ret = krb5_build_cross_realm_tgt(target_realm, &cross_realm_tgt);
    if (ret != 0) {
        free(fqdn);
        return ret;
    }

    request->client = cross_realm_tgt;
    free(fqdn);

    return 0;
}

krb5_int32 prepare_kdc_request(krb5_kdc_req *request, krb5_principal *krbtgt_princ) {
    krb5_int32 ret = 0;
    krb5_boolean canonic = FALSE;

    if ((request->kdc_options & KDC_OPT_CANONICALIZE) != 0) {
        canonic = TRUE;
    }

    if (!canonic || !krbtgt_princ) {
        return 0;
    }

    /* Check server principal name criteria */
    if (krbtgt_princ->name.name_string.len < 2) {
        return KRB5KDCERR_BADOPTION;
    }

    /* Attempt to reprocess the request using the cross-realm TGT */
    ret = krb5_kdc_reprocess_request(request, krbtgt_princ);
    if (ret != 0) {
        return ret;
    }

    return 0;
}

krb5_int32 prepare_kdc_request(krb5_kdc_req *request, krb5_principal *krbtgt_princ) {
    krb5_int32 ret = 0;

    if (request->kdc_options & KDC_OPT_CANONICALIZE) {
        if (krb5_is_krbtgt_principal(*krbtgt_princ)) {
            char *fqdn = NULL;
            krb5_principal cross_realm_tgt = NULL;

            ret = krb5_build_cross_realm_tgt(request->context, *krbtgt_princ, &fqdn, &cross_realm_tgt);
            if (ret != 0) {
                return ret;
            }

            /* Free previous server principal if necessary */
            if (request->server) {
                krb5_free_principal(request->context, request->server);
            }

            request->server = cross_realm_tgt;
            /* Update request with new server principal */
            ret = krb5_kdc_reprocess_request(request, fqdn);
            free(fqdn);
        }
    }

    return ret;
}

krb5_int32 prepare_kdc_request(krb5_kdc_req *request, krb5_principal *krbtgt_princ) {
    krb5_int32 ret = 0;
    krb5_data *server_name = NULL;
    krb5_principal server_principal = NULL;
    krb5_principal cross_realm_tgt = NULL;
    krb5_context context = NULL;

    if ((request->flags & KDC_OPT_CANONICALIZE) == 0) {
        return KRB5_KDC_PATH_NOT_REQUIRED;
    }

    server_name = krb5_principal_get_realm(context, *krbtgt_princ);
    if (server_name == NULL) {
        return KRB5_ERR_NO_REALM;
    }

    if (krb5_is_fqdn(server_name->data)) {
        krb5_data *mapped_realm = krb5_map_fqdn_to_realm(server_name);
        if (mapped_realm == NULL) {
            return KRB5_ERR_MAP_REALM;
        }

        ret = krb5_build_principal(context, &cross_realm_tgt, mapped_realm->length, mapped_realm->data, NULL);
        if (ret != 0) {
            krb5_free_data(context, mapped_realm);
            return ret;
        }

        ret = krb5_copy_principal(context, cross_realm_tgt, &server_principal);
        if (ret != 0) {
            krb5_free_principal(context, cross_realm_tgt);
            krb5_free_data(context, mapped_realm);
            return ret;
        }

        request->sname = krb5_principal_free(context, request->sname);
        request->sname = server_principal;

        request->realm = krb5_free(context, request->realm);
        request->realm = mapped_realm;
    }

    return ret;
}

krb5_int32 prepare_kdc_request(krb5_kdc_req *request, krb5_principal *krbtgt_princ) {
    krb5_int32 retval = 0;
    krb5_data *fqdn_data = NULL;
    krb5_principal new_server = NULL;
    krb5_boolean is_canonicalize = FALSE;

    if (request->kdc_options & KDC_OPT_CANONICALIZE) {
        is_canonicalize = TRUE;
    }

    if (!is_canonicalize || !krbtgt_princ) {
        return 0;
    }

    if (krbtgt_princ->name.name_string.len != 1) {
        return 0;
    }

    fqdn_data = &krbtgt_princ->name.name_string.val[0];
    if (!fqdn_data->length) {
        return 0;
    }

    retval = krb5_build_principal(krb5_context, &new_server, fqdn_data->length, fqdn_data->data, "krbtgt", fqdn_data->data, NULL);
    if (retval) {
        return retval;
    }

    request->client = new_server;

    return 0;
}
